@DisplayName("Modulus: 10 % 3 should be 1")
void testModulus() {
assertEquals(1, calculator.modulus(10, 3), "Modulus of 10 and 3 should be 1");
}
@Test
@DisplayName("Square: 5 squared should be 25")
void testSquare() {
assertEquals(25, calculator.square(5), "Square of 5 should be 25");
